 function attack(){if(attackCooldown>0)return;attackCooldown=.42;let target=actors.find(a=>a.hp>0&&a.mesh.position.distanceTo(player.position)<4);if(target){target.hp--;const pos=target.mesh.position.clone().project(camera);const fx=(pos.x*.5+.5)*innerWidth,fy=(-pos.y*.5+.5)*innerHeight;const f=document.createElement('div');f.className='floattext';f.textContent='− 35';f.style.left=fx+'px';f.style.top=fy+'px';document.querySelector('#game').appendChild(f);setTimeout(()=>f.remove(),850);target.mesh.rotation.y+=.8;if(target.hp<=0){target.mesh.visible=false;target.marker.visible=false;target.respawn=target.boss?18:8;kills++;money+=target.boss?1200:85;bounty+=target.boss?500:25;if(target.boss){const sword=swords.find(x=>!x.owned);if(sword){sword.owned=true;toast(`Boss defeated! You found ${sword.name}!`)}else toast('Boss defeated! +1,200 Beli')}if(questActive&&((questType==='boss'&&target.boss)||(questType==='normal'&&!target.boss))){questProgress=Math.min(questType==='boss'?1:5,questProgress+1);if(questProgress===(questType==='boss'?1:5)){money+=questType==='boss'?1800:250;gainXP(questType==='boss'?1600:420);toast(questType==='boss'?'Boss bounty complete! +1,600 XP · +1,800 Beli':'Quest complete! +420 XP · +250 Beli');questActive=false}}else if(!target.boss)gainXP(45);refreshHUD()} }else toast('No enemy in range — move closer!')}
