+function useAbility(i){const f=fruitData.find(x=>x.name===equipped);toast(`${f.name} ability ${i+1}: ${['Burst','Surge','Awakening'][i]}!`);for(const a of actors){if(a.hp>0&&a.mesh.position.distanceTo(player.position)<7){a.hp=Math.max(0,a.hp-1);if(a.hp===0){a.mesh.visible=false;a.marker.visible=false;a.respawn=a.boss?18:8;money+=a.boss?1200:85;bounty+=a.boss?500:25;if(a.boss){const sword=swords.find(x=>!x.owned);if(sword){sword.owned=true;toast(`Boss defeated! You found ${sword.name}!`)}}if(questActive&&((questType==='boss'&&a.boss)||(questType==='normal'&&!a.boss))){questProgress=Math.min(questType==='boss'?1:5,questProgress+1);if(questProgress===(questType==='boss'?1:5)){money+=questType==='boss'?1800:250;gainXP(questType==='boss'?1600:420);toast('Bounty complete! Reward claimed.');questActive=false}}else if(!a.boss)gainXP(45);refreshHUD()}}}}
 function equipSlot(type){if(type==='fruit'){document.querySelectorAll('.quickslot').forEach(x=>x.classList.remove('active'));document.querySelector('.quickslot:nth-child(2)').classList.add('active');toast(`${equipped} fruit equipped`)}else{document.querySelectorAll('.quickslot').forEach(x=>x.classList.remove('active'));document.querySelector('.quickslot:nth-child(1)').classList.add('active');toast('Saber equipped')}}
 function openModal(which){const wrap=document.querySelector('#modalwrap'),title=document.querySelector('#modalTitle'),sub=document.querySelector('#modalSubtitle'),content=document.querySelector('#modalContent');wrap.classList.add('open');if(which==='inventory'){title.textContent='Your Inventory';sub.textContent='Fruits and swords you have collected.';content.innerHTML=`<div class="tabs"><button class="tab active" data-tab="fruits">✿ Fruits · ${ownedFruits.length}</button><button class="tab" data-tab="swords">⚔ Swords · ${swords.filter(x=>x.owned).length}</button></div><div id="inventoryGrid" class="grid">${fruitCards()}</div>`;content.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{content.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');document.querySelector('#inventoryGrid').innerHTML=t.dataset.tab==='fruits'?fruitCards():swordCards()})}else if(which==='dealer'){title.textContent='Fruit Dealer';sub.textContent='Choose a fruit to equip. All ten fruits are in your collection.';content.innerHTML=`<p class="notice">The dealer keeps a rotating stock of fruits from every rarity. Equip any fruit you own for its abilities.</p><div class="grid">${fruitCards(true)}</div>`}else if(which==='islands'){title.textContent='Island Atlas';sub.textContent='30 islands · 2 seas · Explore at your own pace.';content.innerHTML=`<div class="tabs"><button class="tab active" data-sea="0">FIRST SEA · 15 ISLANDS</button><button class="tab" data-sea="1">SECOND SEA · 15 ISLANDS</button></div><div id="islandGrid" class="islandlist">${islandCards(0)}</div>`;content.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{content.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');document.querySelector('#islandGrid').innerHTML=islandCards(+t.dataset.sea)})}else if(which==='quests'){title.textContent='Quest Board';sub.textContent='Take on normal enemy hunts or challenge a boss for a huge bounty.';content.innerHTML=`<