 function fruitCards(dealer=false){return fruitData.map(f=>`<div class="card"><span class="rarity r-${f.rarity}">${f.rarity}</span><div class="card-icon">${f.icon}</div><strong>${f.name} Fruit ${!dealer?`<button onclick="equipFruit('${f.name}')">${equipped===f.name?'EQUIPPED':'EQUIP'}</button>`:`<button onclick="equipFruit('${f.name}')">EQUIP</button>`}</strong><small>${f.desc}</small></div>`).join('')}
 function swordCards(){return swords.map(s=>`<div class="card"><span class="rarity r-${s.rarity}">${s.owned?'OWNED':s.rarity}</span><div class="card-icon">${s.icon}</div><strong>${s.name} ${s.owned?'<button onclick="toast(\'Sword equipped!\')">EQUIP</button>':''}</strong><small>${s.owned?'Ready for battle.':'Defeat bosses to discover this sword.'}</small></div>`).join('')}

